window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3593c85c2dc45bf5"]={"versions": [{"id": "FIG-3593c85c2dc45bf5", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Zustandsübergangstabelle (State Transition Table) im Kontext der AUTOSAR Adaptive Platform (Interfaces Guidelines). Das Diagramm spezifiziert die Zuordnung von Übergangsanforderungen (Transition Requests) zu Folgezuständen in Abhängigkeit vom aktuellen Zustand einer Zustandsmaschine (StateMachine).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die tabellarische Entität <code>StateMachine TransitionRequestTable</code> gliedert sich in drei Spalten:</p>\n<ul class=\"fig-list\"><li><code>Transition Request</code>: Numerischer Identifikator der Zustandsübergangsanforderung (<code>1000</code>, <code>1001</code>).\n</li><li><code>Current State</code>: Ausgangszustand der Zustandsmaschine als numerischer Wert (<code>0</code>, <code>1</code>, <code>2</code>, <code>3</code>, <code>4</code>).\n</li><li><code>Next State</code>: Zielzustand nach Ausführung der Anforderung als numerischer Wert (<code>0</code>, <code>1</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Tabelle definiert deterministische Zustandswechsel:</p>\n<ul class=\"fig-list\"><li><code>Transition Request</code> 1001 bei <code>Current State</code> 0 führt zu <code>Next State</code> 1.\n</li><li><code>Transition Request</code> 1000 bei <code>Current State</code> 1 führt zu <code>Next State</code> 0.\n</li><li><code>Transition Request</code> 1000 bei <code>Current State</code> 2 führt zu <code>Next State</code> 0.\n</li><li><code>Transition Request</code> 1000 bei <code>Current State</code> 3 führt zu <code>Next State</code> 0.\n</li><li><code>Transition Request</code> 1000 bei <code>Current State</code> 4 führt zu <code>Next State</code> 0.\n</li></ul>\n<p class=\"fig-p\">Alle definierten Übergänge mit Bezeichner 1000 überführen die Zustände 1 bis 4 in den Basiszustand 0.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifikationsbeispiel für die tabellarische Definition von Zustandsübergängen in AUTOSAR AP Service-Schnittstellen bzw. State Management. Entwickler müssen sicherstellen, dass eingehende Transition Requests nur in den hierfür tabellierten Ausgangszuständen gültig sind; nicht aufgeführte Tupel aus Anforderungs-ID und aktuellem Zustand sind abzuweisen oder ungültig. Numerische Bezeichner sind konsistent auf die zugrundeliegenden Enumerations- oder Modus-Definitionen abzubilden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-18626f1a5310b812", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Zustandsübergangstabelle (State Transition Table) im Kontext der AUTOSAR Adaptive Platform (Interfaces Guidelines). Das Diagramm spezifiziert die Zuordnung von Übergangsanforderungen (Transition Requests) zu Folgezuständen in Abhängigkeit vom aktuellen Zustand einer Zustandsmaschine (StateMachine).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die tabellarische Entität <code>StateMachine TransitionRequestTable</code> gliedert sich in drei Spalten:</p>\n<ul class=\"fig-list\"><li><code>Transition Request</code>: Numerischer Identifikator der Übergangsanforderung (<code>1000</code>, <code>1001</code>, <code>1002</code>).\n</li><li><code>Current State</code>: Symbolischer Ausgangszustand der Zustandsmaschine (<code>Off</code>, <code>On</code>, <code>Recovery</code>, <code>Startup</code>, <code>Suspend</code>).\n</li><li><code>Next State</code>: Symbolischer Zielzustand nach Ausführung der Anforderung (<code>Off</code>, <code>On</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Tabelle definiert sechs explizite Zustandsübergänge:</p>\n<ul class=\"fig-list\"><li><code>Transition Request</code> 1001 bei <code>Current State</code> Off führt zu <code>Next State</code> On.\n</li><li><code>Transition Request</code> 1000 bei <code>Current State</code> On führt zu <code>Next State</code> Off.\n</li><li><code>Transition Request</code> 1002 bei <code>Current State</code> Recovery führt zu <code>Next State</code> Off.\n</li><li><code>Transition Request</code> 1001 bei <code>Current State</code> Startup führt zu <code>Next State</code> Off.\n</li><li><code>Transition Request</code> 1000 bei <code>Current State</code> Suspend führt zu <code>Next State</code> On.\n</li><li><code>Transition Request</code> 1000 bei <code>Current State</code> Recovery führt zu <code>Next State</code> Off.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifikationsbeispiel für die tabellarische Definition von Zustandsübergängen in AUTOSAR AP Service-Schnittstellen bzw. State Management. Entwickler müssen sicherstellen, dass Transition Requests gegen die symbolischen Zustände validiert werden. Ungültige Kombinationen (z. B. nicht gelistete Paare aus Request und Zustand) führen zu keinem Wechsel oder müssen fehlerbehandelt werden. Die symbolischen Bezeichner korrespondieren mit den Zustandswerten der jeweiligen State-Machine-Schnittstelle. Am oberen Bildrand ist ein Textfragment aus dem Dokumentenumfeld sichtbar.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-3593c85c2dc45bf5", "to": "FIG-18626f1a5310b812", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Tabelleninhalt: Die Zustandsbezeichner in den Spalten <code>Current State</code> und <code>Next State</code> sind von numerischen Werten (<code>0</code>, <code>1</code>, <code>2</code>, <code>3</code>, <code>4</code>) auf symbolische Zustandsnamen (<code>Off</code>, <code>On</code>, <code>Recovery</code>, <code>Startup</code>, <code>Suspend</code>) umgestellt.\n</li><li>Tabellenzeilen: Zeilenanzahl von 5 auf 6 Einträge erweitert.\n</li><li>Zustandsübergänge: Zusätzliche und modifizierte Übergangsregeln definiert (z. B. <code>1002 | Recovery -&gt; Off</code>, <code>1001 | Startup -&gt; Off</code>, <code>1000 | Suspend -&gt; On</code>).\n</li><li>Layout / Artefakt: Am oberen Bildrand ist eine Textzeile aus dem Fließtextfragment angeschnitten (<code>...SMControl/Application) and 7 of changes in NM...</code>).\n</li></ul>"}]};
